package client

import cats.Applicative
import cats.effect.Async
import fs2.io.file.{Files, Path, PosixPermissions}

/** The newest refresh token Spotify issued, kept between runs. Problems are logged as WARNs, never raised. */
trait TokenStore[F[_]] {

  /** The saved token, or None when there is none or it can't be used. */
  def load: F[Option[String]]

  /** Writes `token` owner-only, creating its directory owner-only if needed. */
  def save(token: String): F[Unit]

  /** Deletes the saved token. */
  def forget: F[Unit]
}

object TokenStore {

  /** Keeps nothing between runs. */
  def none[F[_]: Applicative]: TokenStore[F] = ???

  /** The file at `location`, or `none` with a WARN when there is no location. */
  def at[F[_]: Async: Files](location: Option[Path]): F[TokenStore[F]] = ???

  /** The file at `path`, setting POSIX permissions with `restrict`, which fails where the filesystem has none. */
  def file[F[_]: Async: Files](path: Path, restrict: (Path, PosixPermissions) => F[Unit]): F[TokenStore[F]] = ???
}

package domain.spotify

import io.circe.Codec

/**
 * Port of spotify-credentials.d.ts
 * These are the static credentials required to communicate with Spotify.
 */
case class SpotifyCredentials(
  clientId: String,
  clientSecret: String,
  refreshToken: Option[String] = None,
  tokenFile: Option[String] = None
) derives Codec.AsObject {

  /** The refresh token to start from, if one is configured: `SPOTIFY_REFRESH_TOKEN=` left empty in `.env` counts as none. */
  def configuredRefreshToken: Option[String] = refreshToken.map(_.trim).filter(_.nonEmpty)
}

package client

import cats.effect.*
import cats.effect.implicits.genSpawnOps
import cats.syntax.all.*
import domain.spotify.*
import domain.spotify.types.TrackId
import org.http4s.{client, *}
import org.http4s.client.Client
import org.http4s.circe.CirceEntityCodec.*
import org.http4s.headers.Authorization
import org.http4s.client.dsl.Http4sClientDsl
import org.http4s.ember.server.EmberServerBuilder
import org.http4s.implicits.*
import org.typelevel.log4cats.slf4j.Slf4jLogger
import com.comcast.ip4s.{ipv4, port}

import scala.concurrent.duration.*
import org.http4s.dsl.io.*
