import org.http4s.*
import org.http4s.dsl.Http4sDsl

import scala.util.Random

/** A Spotify call that failed because its certificate couldn't be trusted. */
final case class SpotifyTlsFailure(call: String, cause: Throwable)
    extends RuntimeException(s"Spotify $call failed on its certificate: $cause", cause)

class SpotifyClient[F[_]: Async: Network](
  client: Client[F],
  creds: SpotifyCredentials,
  session: Ref[F, Option[SpotifySession]],
  codes: SignInCodes[F],
  store: TokenStore[F]
) extends Http4sClientDsl[F]:

  /** Keeps the refresh token in memory only. */
  def this(client: Client[F], creds: SpotifyCredentials, session: Ref[F, Option[SpotifySession]], codes: SignInCodes[F]) =
    this(client, creds, session, codes, TokenStore.none[F])

  /** Signs in through the browser at most once, with the code `authCode` is completed with. */
  def this(client: Client[F], creds: SpotifyCredentials, session: Ref[F, Option[SpotifySession]], authCode: Deferred[F, String]) =
    this(client, creds, session, SignInCodes.once[F](authCode), TokenStore.none[F])

  private val authUri = uri"https://accounts.spotify.com/api/token"
  private val apiUri = uri"https://api.spotify.com/v1"

  private val logger = Slf4jLogger.getLogger[F]
  private val random: Random = new Random()

  /** Names `call` in a failure caused by TLS, so the log says which Spotify call couldn't trust the certificate. */
  private def naming[A](call: String)(fa: F[A]): F[A] =
    fa.adaptError { case err if causedByTls(err) => SpotifyTlsFailure(call, err) }

  /** Bounded so a cyclic cause chain can't loop forever. */
  private val MaxCauseDepth = 20

  private def causedByTls(err: Throwable): Boolean =
    Iterator
      .unfold[Throwable, Option[Throwable]](Some(err))(_.map(t => (t, Option(t.getCause))))
      .take(MaxCauseDepth)
      .exists {
        case _: javax.net.ssl.SSLException => true
        case _ => false
      }

  /**
   * Logs the authorize URL, waits for the browser to bring the code back to the callback server, and keeps and saves
   * the refresh token Spotify sends with the exchange.
   */
  def initialAuth: F[String] = ???

  /**
   * Starts a session from the saved refresh token, then the configured one, then the browser sign-in. A saved token
   * Spotify rejects (invalid_grant) is forgotten.
   */
  def signIn: F[String] = ???

  /** The configured refresh token, falling back to the browser sign-in when there is none or Spotify rejects it. */
  private def fromConfigured: F[String] = ???

  /**
   * Helper to always get a valid token.
   */
  def getOrRefresh: F[String] =
    session.get.flatMap:
      case Some(s) => Async[F].pure(s.accessToken)
      case None => signIn

  /**
   * Swaps the refresh token for a new access token, keeping the refresh token Spotify sends back, if any.
   * Spotify's access tokens expire after an hour.
   */
  def renew: F[String] =
    for
      token <- session.get.flatMap {
        case Some(s) => refreshWith("Renew", s.refreshToken)
        case None => creds.configuredRefreshToken.fold(initialAuth)(refreshWith("Renew", _))
      }
      _ <- logger.info("Renewed the Spotify access token")
    yield token

  /**
   * Swaps `refresh` for a new access token and stores the session, keeping `refresh` if Spotify sends no new one and
   * saving the new one if it does. A failure is a `SpotifyTokenError` named `call`.
   */
  private def refreshWith(call: String, refresh: String): F[String] = ???

  /**
   * Sends `request` with the access token. If Spotify rejects the token, renews it and sends the request once more,
   * so `read` only sees a 401 if the renewed token is rejected too.
   */
  private def authorised[A](call: String, request: Request[F])(read: Response[F] => F[A]): F[A] =
    def send(token: String): Resource[F, Response[F]] =
      client.run(request.putHeaders(Authorization(Credentials.Token(AuthScheme.Bearer, token))))

    getOrRefresh
      .flatMap(token =>
        naming(call)(send(token).use(resp => if resp.status == Status.Unauthorized then Async[F].pure(None) else read(resp).map(Some(_))))
      )
      .flatMap {
        case Some(result) => Async[F].pure(result)
        case None => renew.flatMap(token => naming(call)(send(token).use(read)))
      }

  /**
   * Port of fetch-spotify-playback-state.ts
   */
  def getPlaybackState: F[Option[PlaybackState]] =
    authorised("Playback Poll", GET(apiUri / "me" / "player")) { resp =>
      if resp.status == Status.NoContent then Async[F].pure(None)
      else resp.as[PlaybackState].map(Some(_))
    }

  /**
   * The track's tempo in BPM from Spotify's audio features, or None if Spotify won't provide it
   * (the endpoint is restricted for newer Spotify apps).
   */
  def getTempo(id: TrackId): F[Option[Double]] =
    authorised("Tempo Lookup", GET(apiUri / "audio-features" / id.value)) { resp =>
      if resp.status.isSuccess then resp.as[Json].map(_.hcursor.downField("tempo").as[Double].toOption.filter(_ > 0))
      else Async[F].pure(None)
    }

object SpotifyClient:

  /** Where Spotify sends the browser back after sign-in: hands the code it carries to the sign-in waiting for it. */
  def callbackRoutes[F[_]: Async](codes: SignInCodes[F]): HttpRoutes[F] = {
    val dsl = new org.http4s.dsl.Http4sDsl[F] {}
    import dsl.*
    HttpRoutes.of[F] {
      case GET -> Root / "callback" :? CodeMatcher(code) =>
        codes.hand(code) *> Ok("Success! Return to your terminal.")
    }
  }

  def serverResource[F[_]: Async: Network](codes: SignInCodes[F]): Resource[F, org.http4s.server.Server] =
    EmberServerBuilder.default[F].withHost(ipv4"127.0.0.1").withPort(port"7070").withHttpApp(callbackRoutes[F](codes).orNotFound).build

  def resource[F[_]: Async: Network](client: Client[F], creds: SpotifyCredentials, store: TokenStore[F]): Resource[F, SpotifyClient[F]] =
    for
      session <- Resource.eval(Ref.of[F, Option[SpotifySession]](None))
      codes <- Resource.eval(SignInCodes.make[F])
      _ <- serverResource(codes)
    yield new SpotifyClient[F](client, creds, session, codes, store)

  object CodeMatcher extends QueryParamDecoderMatcher[String]("code")

import cats.effect.*
import cats.effect.{ExitCode, IOApp}
import cats.effect.kernel.Resource
import cats.effect.std.Env
import client.{DtlsEmitter, EntertainmentStream, HttpClients, HueClient, SpotifyClient, TokenFile, TokenStore}
import cats.syntax.all.*
import beat.{BeatTracking, TrackerSettings}
import domain.config.{AppConfig, BeatSource}
import domain.hue.{MusicArea, Zone}
import domain.engine.RGB
import settings.{LiveSettings, SettingsRoutes, SettingsServer, ShowControls}
import org.typelevel.log4cats.slf4j.Slf4jLogger
import pureconfig.ConfigSource
import pureconfig.error.ConfigReaderException
object Main extends IOApp {
  private val logger = Slf4jLogger.getLogger[IO]

  private def controls(engine: SyncEngine[IO], lights: Lights[IO]): ShowControls[IO] =
    new ShowControls[IO] {
      def applyNow: IO[Unit] = engine.applyNow
      def areas: IO[List[MusicArea]] = lights.areas
      def palette: IO[Vector[RGB]] = engine.palette.map(_.fold(Vector.empty)(_.colors))
    }

  override def run(args: List[String]): IO[ExitCode] = start(ConfigSource.default)

  def start(source: ConfigSource): IO[ExitCode] = {
    val resources = for {
      config <- Resource.eval(AppConfig.load[IO](source))
      clients <- HttpClients.resource[IO]

      env <- Resource.eval(Env[IO].entries.map(_.toMap))
      store <- Resource.eval(TokenStore.at[IO](TokenFile.locate(config.spotify.tokenFile, env)))
      spotify <- SpotifyClient.resource[IO](clients.spotify, config.spotify, store)
      hueClient = new HueClient[IO](config.hue.creds, clients.bridge)
      emitter = new DtlsEmitter[IO](config.hue.creds)

      lights <- Resource.eval(Lights.fromBridge[IO](hueClient))
      areas <- Resource.eval(lights.areas)
      area <- Resource.eval(MusicArea.choose(areas, config.lightShow.area, config.hue.zoneId).leftMap(new IllegalArgumentException(_)).liftTo[IO])
      _ <- Resource.eval(logger.info(
          s"Entertainment areas on the bridge: ${areas.map(a => s"${a.name} (${a.lights} lights)").mkString(", ")}. Playing on ${area.name}."
        ))
      live <- Resource.eval(LiveSettings.make[IO](config.lightShow.copy(area = Some(area.name)), areas))
      channels <- Resource.eval(hueClient.getChannels(area.id))
      audio = config.lightShow.beatSource match {
        case BeatSource.Audio => BeatTracking.listen[IO](config.lightShow.audio.device, live.applied.map(TrackerSettings.from))
        case BeatSource.Spotify => fs2.Stream.empty
      }
      _ <- Resource.eval(logger.info(
          s"Listening for the beat on '${config.lightShow.audio.device}'. If it never locks on, check that music is playing through it and that your terminal has microphone access."
        ).whenA(config.lightShow.beatSource == BeatSource.Audio))
      engine <- Resource.eval(SyncEngine.make[IO](config, live, spotify, Zone(area.id, channels), lights, audio = audio))
      _ <-
        if (!config.ui.enabled) Resource.unit[IO]
        else
          SettingsServer.resource[IO](config.ui, SettingsRoutes[IO](live, controls(engine, lights)))
            .evalMap(server => logger.info(s"Settings page at ${server.baseUri}; changes take effect when the next song starts"))
    } yield (hueClient, emitter, engine)

    resources.use { (hueClient, emitter, engine) =>
      engine.run.through(EntertainmentStream.toBridge(hueClient, emitter)).compile.drain.as(ExitCode.Success)
    }.recoverWith { case e: ConfigReaderException[?] =>
      logger.error(e.failures.prettyPrint()).as(ExitCode.Error)
    }
  }
}
